"""Writes resource packs into a C++ source file as byte arrays.

Usage: embed_paks.py OUTPUT.cc FUNCTION=INPUT.pak [FUNCTION=INPUT.pak ...]

Each FUNCTION becomes `base::span<const uint8_t> shot::FUNCTION()`, declared
in shot/shot_resources.h, returning the bytes of INPUT.pak.
"""

import sys


def main(argv):
  if len(argv) < 3:
    sys.stderr.write(__doc__)
    return 2
  output = argv[1]
  lines = [
      '// Generated by //shot/embed_paks.py. Do not edit.',
      '',
      '#include "shot/shot_resources.h"',
      '',
      '#include <stdint.h>',
      '',
      'namespace shot {',
      '',
  ]
  for spec in argv[2:]:
    function, separator, path = spec.partition('=')
    if not separator or not function or not path:
      sys.stderr.write('bad argument: %s\n' % spec)
      return 2
    with open(path, 'rb') as f:
      data = f.read()
    if not data:
      sys.stderr.write('empty pack: %s\n' % path)
      return 1
    # Aligned like the page an mmap would have handed DataPack.
    lines.append('alignas(16) static const uint8_t k%s[%d] = {' %
                 (function, len(data)))
    for offset in range(0, len(data), 16):
      lines.append('    ' + ''.join('0x%02x,' % b
                                    for b in data[offset:offset + 16]))
    lines.append('};')
    lines.append('')
    lines.append('base::span<const uint8_t> %s() {' % function)
    lines.append('  return k%s;' % function)
    lines.append('}')
    lines.append('')
  lines.append('}  // namespace shot')
  lines.append('')
  content = '\n'.join(lines)
  try:
    with open(output, 'r', newline='') as f:
      if f.read() == content:
        return 0
  except OSError:
    pass
  with open(output, 'w', newline='\n') as f:
    f.write(content)
  return 0


if __name__ == '__main__':
  sys.exit(main(sys.argv))
